from itertools import permutations

# Define the size of the grid
n = 5

# Fixed assignment
fixed = {2: 3}

# Function to check if a permutation is a Costas array
def is_costas_array(p):
    # Check if all displacement vectors are pairwise distinct
    vectors = set()
    for i in range(n):
        for j in range(i + 1, n):
            dr = p[i] - p[j]
            dc = j - i
            if (dr, dc) in vectors:
                return False
            vectors.add((dr, dc))
    return True

# Find a Costas array consistent with the fixed assignment
for p in permutations(range(n)):
    if all(p[i] == fixed[i] for i in fixed):
        if is_costas_array(p):
            print(p)
            break
else:
    print("UNSATISFIABLE")
